import{_ as c,r as e,o as l,c as i,e as t,a as s,d as n,s as r}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"Хранилище - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Конфигурация","slug":"конфигурация","link":"#конфигурация","children":[{"level":4,"title":"Локальный драйвер","slug":"локальныи-драивер","link":"#локальныи-драивер","children":[]},{"level":4,"title":"Требования к другим драйверам","slug":"требования-к-другим-драиверам","link":"#требования-к-другим-драиверам","children":[]}]},{"level":2,"title":"Основы использования","slug":"основы-использования","link":"#основы-использования","children":[{"level":3,"title":"Получение экземпляров дисков","slug":"получение-экземпляров-дисков","link":"#получение-экземпляров-дисков","children":[]},{"level":3,"title":"Получение файлов","slug":"получение-фаилов","link":"#получение-фаилов","children":[{"level":4,"title":"Метаинформация о файле","slug":"метаинформация-о-фаиле","link":"#метаинформация-о-фаиле","children":[]}]},{"level":3,"title":"Сохранение файлов","slug":"сохранение-фаилов","link":"#сохранение-фаилов","children":[{"level":4,"title":"Добавление в начало / конец файлов","slug":"добавление-в-начало-конец-фаилов","link":"#добавление-в-начало-конец-фаилов","children":[]}]},{"level":3,"title":"Удаление файлов","slug":"удаление-фаилов","link":"#удаление-фаилов","children":[]},{"level":3,"title":"Директории","slug":"директории","link":"#директории","children":[{"level":4,"title":"Получение всех файлов в директории","slug":"получение-всех-фаилов-в-директории","link":"#получение-всех-фаилов-в-директории","children":[]},{"level":4,"title":"Получение всех директорий в директории","slug":"получение-всех-директории-в-директории","link":"#получение-всех-директории-в-директории","children":[]},{"level":4,"title":"Создание директории","slug":"создание-директории","link":"#создание-директории","children":[]},{"level":4,"title":"Удаление директории","slug":"удаление-директории","link":"#удаление-директории","children":[]}]}]}],"relativePath":"3.x/ru/extend/services/storage.md","filePath":"3.x/ru/extend/services/storage.md"}'),u={name:"3.x/ru/extend/services/storage.md"};function d(k,a,g,h,f,v){const p=e("pre-heading"),o=e("post-heading");return l(),i("div",null,[t(p),a[0]||(a[0]=s("h1",null,"Хранилище",-1)),t(o),a[1]||(a[1]=s("p",null,[n("October CMS предоставляет мощную абстракцию файловой системы благодаря Laravel и замечательному PHP-пакету "),s("a",{href:"https://github.com/thephpleague/flysystem",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("Flysystem"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),s("span",{class:"sr-only"},"(opens new window)")])]),n(". Интеграция Flysystem обеспечивает простые в использовании драйверы для работы с локальными файловыми системами и Amazon S3. Более того, переключение между этими вариантами хранения невероятно просто, поскольку API остаётся одинаковым для каждой системы.")],-1)),a[2]||(a[2]=r(`<h2 id="конфигурация"><a href="#конфигурация" class="header-anchor">#</a> Конфигурация</h2><p>Конфигурационный файл файловой системы расположен в <code>config/filesystems.php</code>. В этом файле вы можете настроить все ваши «диски». Каждый диск представляет определённый драйвер хранения и место хранения. Примеры конфигураций для каждого поддерживаемого драйвера включены в конфигурационный файл. Поэтому просто измените конфигурацию, чтобы отразить ваши предпочтения и учётные данные хранения.</p><p>Конечно, вы можете настроить столько дисков, сколько хотите, и даже иметь несколько дисков, использующих один и тот же драйвер.</p><h4 id="локальныи-драивер"><a href="#локальныи-драивер" class="header-anchor">#</a> Локальный драйвер</h4><p>При использовании драйвера <code>local</code> обратите внимание, что все файловые операции выполняются относительно директории <code>root</code>, определённой в вашем конфигурационном файле. По умолчанию это значение установлено в директорию <code>storage/app</code>. Поэтому следующий метод сохранит файл в <code>storage/app/file.txt</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;local&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.txt&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Contents&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="требования-к-другим-драиверам"><a href="#требования-к-другим-драиверам" class="header-anchor">#</a> Требования к другим драйверам</h4><p>Перед использованием драйвера S3 вам необходимо установить пакет Flysystem S3 через менеджер пакетов Composer.</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> require league/flysystem-aws-s3-v3 <span class="token string">&quot;^3.0&quot;</span>
</code></pre></div><p>Конфигурационная информация драйвера S3 находится в вашем конфигурационном файле <code>config/filesystems.php</code>. Этот файл содержит пример массива конфигурации для драйвера S3. Вы можете свободно изменять этот массив, указав собственную конфигурацию и учётные данные S3.</p><h2 id="основы-использования"><a href="#основы-использования" class="header-anchor">#</a> Основы использования</h2><h3 id="получение-экземпляров-дисков"><a href="#получение-экземпляров-дисков" class="header-anchor">#</a> Получение экземпляров дисков</h3><p>Фасад <code>Storage</code> может использоваться для взаимодействия с любым из ваших настроенных дисков. Например, вы можете использовать метод <code>put</code> на фасаде для сохранения аватара на диске по умолчанию. Если вы вызываете методы на фасаде <code>Storage</code> без предварительного вызова метода <code>disk</code>, вызов метода будет автоматически передан на диск по умолчанию:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token variable">$id</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span>
    <span class="token string single-quoted-string">&#39;avatars/&#39;</span><span class="token operator">.</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">,</span>
    <span class="token function">file_get_contents</span><span class="token punctuation">(</span><span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;avatar&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">getRealPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>При использовании нескольких дисков вы можете получить доступ к определённому диску с помощью метода <code>disk</code> фасада <code>Storage</code>. Конечно, вы можете продолжать цепочку методов для выполнения операций на диске:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$disk</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;s3&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$contents</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;local&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">)</span>
</code></pre></div><h3 id="получение-фаилов"><a href="#получение-фаилов" class="header-anchor">#</a> Получение файлов</h3><p>Метод <code>get</code> может использоваться для получения содержимого заданного файла. Метод вернёт необработанное строковое содержимое файла:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$contents</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>exists</code> может использоваться для определения, существует ли заданный файл на диске:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$exists</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">disk</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;s3&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">exists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="метаинформация-о-фаиле"><a href="#метаинформация-о-фаиле" class="header-anchor">#</a> Метаинформация о файле</h4><p>Метод <code>size</code> может использоваться для получения размера файла в байтах:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$size</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">size</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file1.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>lastModified</code> возвращает UNIX-метку времени последнего изменения файла:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$time</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">lastModified</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file1.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="сохранение-фаилов"><a href="#сохранение-фаилов" class="header-anchor">#</a> Сохранение файлов</h3><p>Метод <code>put</code> может использоваться для сохранения файла на диск. Вы также можете передать PHP-<code>resource</code> в метод <code>put</code>, который будет использовать поддержку потоков Flysystem. Использование потоков настоятельно рекомендуется при работе с большими файлами:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">,</span> <span class="token variable">$contents</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">,</span> <span class="token variable">$resource</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>copy</code> может использоваться для копирования существующего файла в новое расположение на диске:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">copy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;old/file1.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;new/file1.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>move</code> может использоваться для перемещения существующего файла в новое расположение:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">move</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;old/file1.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;new/file1.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="добавление-в-начало-конец-фаилов"><a href="#добавление-в-начало-конец-фаилов" class="header-anchor">#</a> Добавление в начало / конец файлов</h4><p>Методы <code>prepend</code> и <code>append</code> позволяют легко вставлять содержимое в начало или конец файла:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">prepend</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.log&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Prepended Text&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">append</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.log&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Appended Text&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="удаление-фаилов"><a href="#удаление-фаилов" class="header-anchor">#</a> Удаление файлов</h3><p>Метод <code>delete</code> принимает одно имя файла или массив файлов для удаления с диска:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;file1.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;file2.jpg&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="директории"><a href="#директории" class="header-anchor">#</a> Директории</h3><h4 id="получение-всех-фаилов-в-директории"><a href="#получение-всех-фаилов-в-директории" class="header-anchor">#</a> Получение всех файлов в директории</h4><p>Метод <code>files</code> возвращает массив всех файлов в заданной директории. Если вы хотите получить список всех файлов в заданной директории, включая все поддиректории, вы можете использовать метод <code>allFiles</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$files</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">files</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$files</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">allFiles</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="получение-всех-директории-в-директории"><a href="#получение-всех-директории-в-директории" class="header-anchor">#</a> Получение всех директорий в директории</h4><p>Метод <code>directories</code> возвращает массив всех директорий в заданной директории. Кроме того, вы можете использовать метод <code>allDirectories</code> для получения списка всех директорий в заданной директории и всех её поддиректориях:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$directories</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">directories</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Recursive...</span>
<span class="token variable">$directories</span> <span class="token operator">=</span> <span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">allDirectories</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="создание-директории"><a href="#создание-директории" class="header-anchor">#</a> Создание директории</h4><p>Метод <code>makeDirectory</code> создаст заданную директорию, включая все необходимые поддиректории:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">makeDirectory</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="удаление-директории"><a href="#удаление-директории" class="header-anchor">#</a> Удаление директории</h4><p>Наконец, метод <code>deleteDirectory</code> может использоваться для удаления директории, включая все её файлы, с диска:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Storage</span><span class="token operator">::</span><span class="token function">deleteDirectory</span><span class="token punctuation">(</span><span class="token variable">$directory</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,52))])}const S=c(u,[["render",d]]);export{m as __pageData,S as default};
